1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Damage = {
18	  itemType: string;
19	  amount: number;
20	};
21	
22	export type Incident = {
23	  cause: string;
24	  damages: Damage[];
25	};
