44	const PROCESSING_FEE = 5;
45	
46	// Only the main item types. Components are priced separately: individually,
47	// or as a discounted block of 3 alike ones.
48	const BASE_PREMIUMS: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	};
54	
55	// Insurance values are the SUM INSURED per item - distinct from the base
56	// premiums above, which price the policy.
57	const INSURANCE_VALUES: Record<string, number> = {
58	  sword: 1000,
59	  amulet: 600,
60	  staff: 800,
61	  potion: 400,
62	};
63	
64	const COMPONENT_INSURANCE_VALUE = 250;
65	const DEDUCTIBLE_PER_DAMAGE = 100;
66	
67	// A CLAIM-side rule, unrelated to the premium-side
68	// ENCHANTMENT_SURCHARGE_THRESHOLD of 5; the two merely both key off
69	// enchantment, and are deliberately kept as separate numbers.
70	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
71	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
72	const CAP_MULTIPLE = 2;
73	
74	const COMPONENT_TYPES = ["rune", "moonstone"];
75	const COMPONENT_BASE_PREMIUM = 25;
76	const BLOCK_SIZE = 3;
77	const BLOCK_BASE_PREMIUM = 60;
78	
79	const isComponent = (item: Item): boolean =>
80	  COMPONENT_TYPES.includes(item.type);
81	
82	// Modifiers are additive percentages of the UNMODIFIED base premium, never
83	// compounding multipliers, and are kept as exact fractions rather than float
84	// multipliers: 100 * 1.1 is 110.00000000000001 in IEEE-754. Only the final
85	// premium is rounded, so intermediate amounts stay fractional.
86	const percentOf = (amount: number, percent: number): number =>
87	  (amount * percent) / 100;
88	
89	// Modifiers are signed terms in one additive sum, so a discount is simply a
90	// negative percentage. Naming the sign keeps it from riding on a single easily
91	// overlooked "-" at a call site.
92	const discountOf = (amount: number, percent: number): number =>
93	  -percentOf(amount, percent);
94	
95	const FIRST_INSURANCE_PERCENT = 10;
96	const CURSE_PERCENT = 50;
97	const HIGH_ENCHANTMENT_PERCENT = 30;
98	const ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
99	const LOYALTY_DISCOUNT_PERCENT = 20;
100	const LOYALTY_THRESHOLD_YEARS = 2;
101	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
102	
103	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
104	
105	// A group of exactly 3 alike components is offered at a block price. Any
106	// other count is priced per component.
107	const componentGroupPremium = (count: number): number =>
108	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
109	
110	// Components are priced per group of alike ones, so each distinct type is
111	// counted and priced on its own.
112	const componentsPremium = (components: Item[]): number => {
113	  const distinctTypes = new Set(components.map((component) => component.type));
114	
115	  return [...distinctTypes].reduce((sum, type) => {
116	    const alike = components.filter((component) => component.type === type);
117	    return sum + componentGroupPremium(alike.length);
118	  }, 0);
119	};
120	
121	// Splits a quote's items into the two independently-priced kinds, so the
122	// main/component distinction is decided in exactly one place.
123	const partitionByComponent = (
124	  items: Item[],
125	): { mainItems: Item[]; components: Item[] } => ({
126	  mainItems: items.filter((item) => !isComponent(item)),
127	  components: items.filter(isComponent),
128	});
129	
130	// Item-specific modifiers apply to the affected item's OWN base premium, not
131	// to the policy total. They are independent: a cursed, highly enchanted item
132	// carries both, so each item sums the surcharges that apply to it.
133	// Named for the consequence rather than the measurement, so it cannot be
134	// mistaken for the claim-side qualifiesForHalfReimbursement below.
135	const attractsEnchantmentSurcharge = (item: Item): boolean =>
136	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_THRESHOLD;
137	
138	const surchargesFor = (item: Item): number => {
139	  const base = basePremiumOf(item);
140	  const curse = item.cursed ? percentOf(base, CURSE_PERCENT) : 0;
141	  const enchantment = attractsEnchantmentSurcharge(item)
142	    ? percentOf(base, HIGH_ENCHANTMENT_PERCENT)
143	    : 0;
144	
145	  return curse + enchantment;
146	};
147	
148	const itemSpecificModifiers = (mainItems: Item[]): number =>
149	  mainItems.reduce((sum, item) => sum + surchargesFor(item), 0);
150	
151	// Policy-wide modifiers are percentages of the whole policy's base premium,
152	// taken from the UNMODIFIED base so item-specific modifiers never feed into
153	// them - that is what keeps modifiers additive instead of compounding.
154	// Discounts are negative terms.
155	const qualifiesForLoyalty = (customer: Customer): boolean =>
156	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
157	
158	const policyWideModifiers = (
159	  basePremium: number,
160	  customer: Customer,
161	  isFollowUp: boolean,
162	): number => {
163	  // First insurance applies to every quote, including follow-ups: the spec
164	  // treats each item in a quote as a first insurance regardless of customer
165	  // history, so this coexists with the follow-up discount.
166	  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
167	  const loyalty = qualifiesForLoyalty(customer)
168	    ? discountOf(basePremium, LOYALTY_DISCOUNT_PERCENT)
169	    : 0;
170	  const followUp = isFollowUp
171	    ? discountOf(basePremium, FOLLOW_UP_DISCOUNT_PERCENT)
172	    : 0;
173	
174	  return firstInsurance + loyalty + followUp;
175	};
176	
177	// Amounts are rounded in the MHPCO's favor, and the direction depends on who
178	// pays: a premium is owed TO MHPCO, so it rounds up. (A payout is owed BY
179	// MHPCO, so it will round down - hence the rule, not the direction, is what
180	// this name states.) Applied once, where a step's result is emitted: every
181	// amount inside the pricing pipeline stays an exact fraction.
182	const roundPremiumInMhpcoFavor = (premium: number): number =>
183	  Math.ceil(premium);
184	
185	// Returns the EXACT, unrounded premium. Rounding happens once, at the point
186	// the result is emitted - see runScenario.
187	const quotePremium = (
188	  step: QuoteStep,
189	  customer: Customer,
190	  isFollowUp: boolean,
191	): number => {
192	  const { mainItems, components } = partitionByComponent(step.items);
193	
194	  const basePremium =
195	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
196	    componentsPremium(components);
197	
198	  const modifiers =
199	    itemSpecificModifiers(mainItems) +
200	    policyWideModifiers(basePremium, customer, isFollowUp);
201	
202	  return basePremium + modifiers + PROCESSING_FEE;
203	};
204	
205	const insuranceValueOf = (item: Item): number =>
206	  isComponent(item) ? COMPONENT_INSURANCE_VALUE : INSURANCE_VALUES[item.type];
207	
208	// The insurance sum is a plain per-item total: the component block discount
209	// affects the premium only, never the sum insured.
210	const insuranceSumOf = (items: Item[]): number =>
211	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
212	
213	// A policy remembers what it covers and how much of its cap is left, so later
214	// claim steps can draw against it.
215	type Policy = {
216	  items: Item[];
217	  remainingCap: number;
218	};
219	
220	const openPolicy = (items: Item[]): Policy => ({
221	  items,
222	  remainingCap: CAP_MULTIPLE * insuranceSumOf(items),
223	});
224	
225	// Damage to a sufficiently enchanted item is only half reimbursed. Named for
226	// the consequence rather than the measurement, so it cannot be mistaken for
227	// the premium-side attractsEnchantmentSurcharge above.
228	const qualifiesForHalfReimbursement = (item: Item): boolean =>
229	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
230	
231	// Decides how much of a damage amount the clauses cover, before the
232	// deductible. Takes the amount rather than the whole Damage: the itemType has
233	// already been resolved to an item by the caller.
234	const reimbursementFor = (item: Item, amount: number): number =>
235	  qualifiesForHalfReimbursement(item)
236	    ? percentOf(amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
237	    : amount;
238	
239	// Each damage entry carries its own deductible, applied after the
240	// reimbursement clauses have decided how much of the damage is covered.
241	const payoutForDamage = (policy: Policy, damage: Damage): number => {
242	  const damagedItem = policy.items.find(
243	    (item) => item.type === damage.itemType,
244	  ) as Item;
245	
246	  return reimbursementFor(damagedItem, damage.amount) - DEDUCTIBLE_PER_DAMAGE;
247	};
248	
249	const settleClaim = (policy: Policy, incident: Incident): number =>
250	  incident.damages.reduce(
251	    (total, damage) => total + payoutForDamage(policy, damage),
252	    0,
253	  );
254	
255	type QuoteResult = { premium: number };
256	type ClaimResult = { payout: number; remainingCap: number };
257	
258	// Settling draws the payout against the policy's cap, so the policy carries
259	// less cover into any later claim.
260	// The cap limits the money actually paid out, not just the reported
261	// remainder: once it is exhausted the desired payout is cut down to whatever
262	// cover is left, and the remainder floors at 0.
263	const limitToRemainingCap = (desired: number, policy: Policy): number =>
264	  Math.min(desired, policy.remainingCap);
265	
266	const drawAgainstPolicy = (policy: Policy, incident: Incident): ClaimResult => {
267	  const payout = limitToRemainingCap(settleClaim(policy, incident), policy);
268	
269	  policy.remainingCap -= payout;
270	
271	  return { payout, remainingCap: policy.remainingCap };
272	};
273	
274	const priceQuote = (
275	  step: QuoteStep,
276	  customer: Customer,
277	  isFollowUp: boolean,
278	): QuoteResult => ({
279	  premium: roundPremiumInMhpcoFavor(quotePremium(step, customer, isFollowUp)),
280	});
281	
282	export const runScenario = (scenario: Scenario): ScenarioResult => {
283	  // Policies are keyed by the step index of the quote that created them, which
284	  // is how claim steps reference them.
285	  const policies = new Map<number, Policy>();
286	
287	  // The follow-up discount depends on how many QUOTES preceded this one, which
288	  // is not the step index once claim steps are interleaved.
289	  let quotesSoFar = 0;
290	
291	  const results = scenario.steps.map((step, stepIndex) => {
292	    if (step.op === "claim") {
293	      return drawAgainstPolicy(
294	        policies.get(step.policy) as Policy,
295	        step.incident,
296	      );
297	    }
298	
299	    policies.set(stepIndex, openPolicy(step.items));
300	    const isFollowUp = quotesSoFar > 0;
301	    quotesSoFar += 1;
302	
303	    return priceQuote(step, scenario.customer, isFollowUp);
304	  });
305	
306	  return { results };
307	};
